package yagen.waitmydawn.kb.service;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class EntityCompositionInfoTest {
 final ObjectMapper json=new ObjectMapper();
 ObjectNode row(){var row=json.createObjectNode();var c=row.putObject("composition").put("schemaVersion",1).put("adapter","example:adapter").put("adapterVersion","1").put("status","COMPLETE").put("rootVisibleExpected",true).put("reason","");c.putObject("extra");var n=c.putArray("parts").addObject().put("key","body").put("parent","root").put("id","minecraft:pig").put("policy","INDEPENDENT").put("visibleExpected",true).put("transformSpace","ROOT_LOCAL").put("x",1).put("y",0).put("z",0).put("yaw",0).put("pitch",0).put("bodyYaw",0).put("headYaw",0).put("dataHash","a".repeat(64)).put("syncedHash","b".repeat(64));row.putObject("compositionRender").put("status","COMPLETE").put("total",2).putArray("noVisiblePixels");return row;}
 @Test void completeAndLegacyDescriptionsAreDistinct()throws Exception{var row=row();EntityCompositionInfo.validate(row);assertTrue(EntityCompositionInfo.caption(row).contains("组成已验证"));assertEquals("",EntityCompositionInfo.caption(json.createObjectNode()));row.withObject("composition").put("status","PARTIAL").put("reason","Missing tail");EntityCompositionInfo.validate(row);assertTrue(EntityCompositionInfo.caption(row).contains("Missing tail"));}
 @Test void cyclesUnknownCompleteAndNonFiniteTransformsAreRejected(){for(String kind:java.util.List.of("cycle","unknown","nan","hash")){var row=row();var node=(ObjectNode)row.path("composition").path("parts").get(0);switch(kind){case "cycle"->node.put("parent","body");case "unknown"->node.put("policy","UNKNOWN");case "nan"->node.put("x",Double.NaN);case "hash"->node.put("dataHash","bad");}assertThrows(java.io.IOException.class,()->EntityCompositionInfo.validate(row),kind);}}
 @Test void duplicateNodesAndStateMismatchAreRejected(){var row=row();((ArrayNode)row.path("composition").path("parts")).add(row.path("composition").path("parts").get(0).deepCopy());assertThrows(java.io.IOException.class,()->EntityCompositionInfo.validate(row));var mismatch=row();mismatch.putObject("state").putObject("traits").putObject("composition").put("status","PARTIAL");assertThrows(java.io.IOException.class,()->EntityCompositionInfo.validate(mismatch));}
 @Test void invisibleIndependentPartCannotClaimACompleteRenderedComposition()throws Exception {var row=row();row.withObject("compositionRender").put("status","PARTIAL").withArray("noVisiblePixels").add("body");EntityCompositionInfo.validate(row);assertTrue(EntityCompositionInfo.caption(row).contains("未取得可见像素"));row.withObject("compositionRender").put("status","COMPLETE");assertThrows(java.io.IOException.class,()->EntityCompositionInfo.validate(row));}
 @org.junit.jupiter.api.Test void missingRootIsDistinctFromAnExplicitContainer()throws Exception {
 var row=row();var check=(com.fasterxml.jackson.databind.node.ObjectNode)row.path("compositionRender");check.put("status","PARTIAL");((com.fasterxml.jackson.databind.node.ArrayNode)check.path("noVisiblePixels")).add("root");EntityCompositionInfo.validate(row);org.junit.jupiter.api.Assertions.assertTrue(EntityCompositionInfo.caption(row).contains("部分外观"));
 ((com.fasterxml.jackson.databind.node.ObjectNode)row.path("composition")).put("rootVisibleExpected",false);org.junit.jupiter.api.Assertions.assertThrows(java.io.IOException.class,()->EntityCompositionInfo.validate(row));
 }
 @Test void longBodyChainsAndNoVisibilityProofAreValidated()throws Exception{var row=row();var parts=(com.fasterxml.jackson.databind.node.ArrayNode)row.path("composition").path("parts");var template=parts.get(0).deepCopy();parts.removeAll();for(int i=0;i<40;i++){var node=(com.fasterxml.jackson.databind.node.ObjectNode)template.deepCopy();node.put("key","body_"+i).put("parent",i==0?"root":"body_"+(i-1));parts.add(node);}((com.fasterxml.jackson.databind.node.ObjectNode)row.path("compositionRender")).put("total",41);EntityCompositionInfo.validate(row);var invisible=row();((com.fasterxml.jackson.databind.node.ObjectNode)invisible.path("composition")).put("rootVisibleExpected",false);((com.fasterxml.jackson.databind.node.ObjectNode)invisible.path("composition").path("parts").get(0)).put("visibleExpected",false);((com.fasterxml.jackson.databind.node.ObjectNode)invisible.path("compositionRender")).put("status","NOT_REQUIRED");EntityCompositionInfo.validate(invisible);assertTrue(EntityCompositionInfo.caption(invisible).contains("不能据此证明"));}
}
